18	package org.keycloak.util;
19	
20	import java.io.IOException;
21	import java.security.PublicKey;
22	import java.util.ArrayList;
23	import java.util.HashMap;
24	import java.util.List;
25	import java.util.Map;
26	import java.util.TreeMap;
27	import java.util.stream.Collectors;
28	
29	import org.keycloak.common.util.Base64Url;
30	import org.keycloak.crypto.KeyType;
31	import org.keycloak.crypto.KeyUse;
32	import org.keycloak.crypto.KeyWrapper;
33	import org.keycloak.crypto.PublicKeysWrapper;
34	import org.keycloak.jose.jwk.ECPublicJWK;
35	import org.keycloak.jose.jwk.JSONWebKeySet;
36	import org.keycloak.jose.jwk.JWK;
37	import org.keycloak.jose.jwk.JWKParser;
38	import org.keycloak.jose.jwk.OKPPublicJWK;
39	import org.keycloak.jose.jwk.RSAPublicJWK;
40	import org.keycloak.jose.jws.crypto.HashUtils;
41	import org.keycloak.json.KeycloakJsonMapperFactory;
42	
43	import org.jboss.logging.Logger;
44	
45	/**
46	 * @author <a href="mailto:mposolda@redhat.com">Marek Posolda</a>
47	 */
48	public class JWKSUtils {
49	
50	    private static final Logger logger = Logger.getLogger(JWKSUtils.class.getName());
51	
52	    private static final String JWK_THUMBPRINT_DEFAULT_HASH_ALGORITHM = "SHA-256";
53	    private static final Map<String, String[]> JWK_THUMBPRINT_REQUIRED_MEMBERS = new HashMap<>();
54	
55	    static {
56	        JWK_THUMBPRINT_REQUIRED_MEMBERS.put(KeyType.RSA, new String[] { RSAPublicJWK.MODULUS, RSAPublicJWK.PUBLIC_EXPONENT });
57	        JWK_THUMBPRINT_REQUIRED_MEMBERS.put(KeyType.EC, new String[] { ECPublicJWK.CRV, ECPublicJWK.X, ECPublicJWK.Y });
58	        JWK_THUMBPRINT_REQUIRED_MEMBERS.put(KeyType.OKP, new String[] { OKPPublicJWK.CRV, OKPPublicJWK.X });
59	    }
60	
61	    /**
62	     * @deprecated Use {@link #getKeyWrappersForUse(JSONWebKeySet, JWK.Use)}
63	     **/
64	    @Deprecated
65	    public static Map<String, PublicKey> getKeysForUse(JSONWebKeySet keySet, JWK.Use requestedUse) {
66	        return getKeyWrappersForUse(keySet, requestedUse).getKeys()
67	                .stream()
68	                .collect(Collectors.toMap(KeyWrapper::getKid, keyWrapper -> (PublicKey) keyWrapper.getPublicKey()));
69	    }
70	
71	    public static PublicKeysWrapper getKeyWrappersForUse(JSONWebKeySet keySet, JWK.Use requestedUse) {
72	        return getKeyWrappersForUse(keySet, requestedUse, false);
73	    }
74	
75	    public static PublicKeysWrapper getKeyWrappersForUse(JSONWebKeySet keySet, JWK.Use requestedUse, boolean useRequestedUseWhenNull) {
76	        List<KeyWrapper> result = new ArrayList<>();
77	        for (JWK jwk : keySet.getKeys()) {
78	            JWKParser parser = JWKParser.create(jwk);
79	            if (jwk.getPublicKeyUse() == null && !useRequestedUseWhenNull) {
80	                logger.debugf("Ignoring JWK key '%s'. Missing required field 'use'.", jwk.getKeyId());
81	            } else if ((requestedUse.asString().equals(jwk.getPublicKeyUse()) || (jwk.getPublicKeyUse() == null && useRequestedUseWhenNull))
82	                    && parser.isKeyTypeSupported(jwk.getKeyType())) {
83	                try {
84	                    KeyWrapper keyWrapper = wrap(jwk, parser, false);
85	                    keyWrapper.setUse(getKeyUse(requestedUse.asString()));
86	                    result.add(keyWrapper);
87	                } catch (RuntimeException e) {
88	                    logger.debugf(e, "Ignoring JWK key '%s'. Failed to load key.", jwk.getKeyId());
89	                }
90	            }
91	        }
92	        return new PublicKeysWrapper(result);
93	    }
94	
95	    private static KeyUse getKeyUse(String keyUse) {
96	        if (keyUse == null) {
97	            return null;
98	        } else switch (keyUse) {
99	            case "sig" :
100	                return KeyUse.SIG;
101	            case "enc" :
102	                return KeyUse.ENC;
103	            default :
104	                return null;
105	        }
106	    }
107	
108	    public static JWK getKeyForUse(JSONWebKeySet keySet, JWK.Use requestedUse) {
109	        for (JWK jwk : keySet.getKeys()) {
110	            JWKParser parser = JWKParser.create(jwk);
111	            if (jwk.getPublicKeyUse() == null) {
112	                logger.debugf("Ignoring JWK key '%s'. Missing required field 'use'.", jwk.getKeyId());
113	            } else if (requestedUse.asString().equals(parser.getJwk().getPublicKeyUse()) && parser.isKeyTypeSupported(jwk.getKeyType())) {
114	                return jwk;
115	            }
116	        }
117	
118	        return null;
119	    }
120	
121	    public static KeyWrapper getKeyWrapper(JWK jwk) {
122	        return getKeyWrapper(jwk, false);
123	    }
124	
125	    public static KeyWrapper getKeyWrapper(JWK jwk, boolean skipPublicKey) {
126	        JWKParser parser = JWKParser.create(jwk);
127	        if (parser.isKeyTypeSupported(jwk.getKeyType())) {
128	            return wrap(jwk, parser, skipPublicKey);
129	        } else {
130	            return null;
131	        }
132	    }
133	
134	    private static KeyWrapper wrap(JWK jwk, JWKParser parser, boolean skipPublicKey) {
135	        KeyWrapper keyWrapper = new KeyWrapper();
136	        keyWrapper.setKid(jwk.getKeyId());
137	        if (jwk.getAlgorithm() != null) {
138	            keyWrapper.setAlgorithm(jwk.getAlgorithm());
139	        }
140	        if (jwk.getOtherClaim(OKPPublicJWK.CRV, String.class) != null) {
141	            keyWrapper.setCurve(jwk.getOtherClaim(OKPPublicJWK.CRV, String.class));
142	        }
143	        keyWrapper.setType(jwk.getKeyType());
144	        keyWrapper.setUse(getKeyUse(jwk.getPublicKeyUse()));
145	        if (!skipPublicKey) {
146	            keyWrapper.setPublicKey(parser.toPublicKey());
147	        }
148	        return keyWrapper;
149	    }
150	
151	    public static String computeThumbprint(JWK key)  {
152	        return computeThumbprint(key, JWK_THUMBPRINT_DEFAULT_HASH_ALGORITHM);
153	    }
154	
155	    // TreeMap uses the natural ordering of the keys.
156	    // Therefore, it follows the way of hash value calculation for a public key defined by RFC 7638
157	    public static String computeThumbprint(JWK key, String hashAlg)  {
158	        String kty = key.getKeyType();
159	        String[] requiredMembers = JWK_THUMBPRINT_REQUIRED_MEMBERS.get(kty);
160	
161	        // e.g. `oct`, see RFC 7638 Section 3.2
162	        if (requiredMembers == null) {
163	            throw new UnsupportedOperationException("Unsupported key type: " + kty);
164	        }
165	
166	        Map<String, String> members = new TreeMap<>();
167	        members.put(JWK.KEY_TYPE, kty);
168	
169	        try {
170	            for (String member : requiredMembers) {
171	                members.put(member, key.getOtherClaim(member, String.class));
172	            }
173	
174	            byte[] bytes = KeycloakJsonMapperFactory.mapper().writeValueAsBytes(members);
175	            byte[] hash = HashUtils.hash(hashAlg, bytes);
176	            return Base64Url.encode(hash);
177	        } catch (IOException ex) {
178	            logger.debugf(ex, "Failed to compute JWK thumbprint for key '%s'.", key.getKeyId());
179	            return null;
180	        }
181	    }
182	
183	}
