1	package org.keycloak.util;
2	
3	import org.keycloak.crypto.AsymmetricSignatureSignerContext;
4	import org.keycloak.crypto.AsymmetricSignatureVerifierContext;
5	import org.keycloak.crypto.ECDSASignatureSignerContext;
6	import org.keycloak.crypto.ECDSASignatureVerifierContext;
7	import org.keycloak.crypto.KeyType;
8	import org.keycloak.crypto.KeyWrapper;
9	import org.keycloak.crypto.SignatureSignerContext;
10	import org.keycloak.crypto.SignatureVerifierContext;
11	
12	public class KeyWrapperUtil {
13	
14	    public static SignatureSignerContext createSignatureSignerContext(KeyWrapper keyWrapper) {
15	        switch (keyWrapper.getType()) {
16	            case KeyType.EC:
17	                return new ECDSASignatureSignerContext(keyWrapper);
18	            case KeyType.RSA:
19	            case KeyType.OKP:
20	                return new AsymmetricSignatureSignerContext(keyWrapper);
21	            default:
22	                throw new IllegalArgumentException("No signer provider for key algorithm type " + keyWrapper.getType());
23	        }
24	    }
25	
26	    public static SignatureVerifierContext createSignatureVerifierContext(KeyWrapper keyWrapper) {
27	        switch (keyWrapper.getType()) {
28	            case KeyType.EC:
29	                return new ECDSASignatureVerifierContext(keyWrapper);
30	            case KeyType.RSA:
31	            case KeyType.OKP:
32	                return new AsymmetricSignatureVerifierContext(keyWrapper);
33	            default:
34	                throw new IllegalArgumentException("No signer provider for key algorithm type " + keyWrapper.getType());
35	        }
36	    }
37	
38	    private KeyWrapperUtil() {
39	    }
40	}
