17	package org.keycloak.crypto;
18	
19	import java.security.PrivateKey;
20	import java.security.Signature;
21	import java.security.cert.X509Certificate;
22	import java.util.Collections;
23	import java.util.List;
24	
25	public class AsymmetricSignatureSignerContext implements SignatureSignerContext {
26	
27	    protected final KeyWrapper key;
28	
29	    public AsymmetricSignatureSignerContext(KeyWrapper key) throws SignatureException {
30	        this.key = key;
31	    }
32	
33	    @Override
34	    public String getKid() {
35	        return key.getKid();
36	    }
37	
38	    @Override
39	    public String getAlgorithm() {
40	        return key.getAlgorithmOrDefault();
41	    }
42	
43	    @Override
44	    public String getHashAlgorithm() {
45	        return JavaAlgorithm.getJavaAlgorithmForHash(key.getAlgorithmOrDefault(), key.getCurve());
46	    }
47	
48	    @Override
49	    public byte[] sign(byte[] data) throws SignatureException {
50	        try {
51	            Signature signature = Signature.getInstance(JavaAlgorithm.getJavaAlgorithm(key.getAlgorithmOrDefault(), key.getCurve()));
52	            signature.initSign((PrivateKey) key.getPrivateKey());
53	            signature.update(data);
54	            return signature.sign();
55	        } catch (Exception e) {
56	            throw new SignatureException("Signing failed", e);
57	        }
58	    }
59	
60	    @Override
61	    public List<X509Certificate> getCertificateChain() {
62	        if (key.getCertificateChain() != null && !key.getCertificateChain().isEmpty()) {
63	            return key.getCertificateChain();
64	        } else if (key.getCertificate() != null) {
65	            return Collections.singletonList(key.getCertificate());
66	        }
67	        return null;
68	    }
69	
70	}
