17	package org.keycloak.crypto;
18	
19	import java.security.NoSuchAlgorithmException;
20	import java.security.NoSuchProviderException;
21	import java.security.PublicKey;
22	import java.security.Signature;
23	
24	import org.keycloak.common.VerificationException;
25	import org.keycloak.common.crypto.CryptoIntegration;
26	
27	public class AsymmetricSignatureVerifierContext implements SignatureVerifierContext {
28	
29	    private final KeyWrapper key;
30	
31	    public AsymmetricSignatureVerifierContext(KeyWrapper key) {
32	        this.key = key;
33	    }
34	
35	    @Override
36	    public String getKid() {
37	        return key.getKid();
38	    }
39	
40	    @Override
41	    public String getAlgorithm() {
42	        return key.getAlgorithmOrDefault();
43	    }
44	
45	    @Override
46	    public boolean verify(byte[] data, byte[] signature) throws VerificationException {
47	        try {
48	            Signature verifier = getSignature();
49	            verifier.initVerify((PublicKey) key.getPublicKey());
50	            verifier.update(data);
51	            return verifier.verify(signature);
52	        } catch (Exception e) {
53	            throw new VerificationException("Signing failed", e);
54	        }
55	    }
56	
57	    private Signature getSignature()
58	            throws NoSuchAlgorithmException, NoSuchProviderException {
59	        try {
60	            return Signature.getInstance(JavaAlgorithm.getJavaAlgorithm(key.getAlgorithmOrDefault(), key.getCurve()));
61	        } catch (NoSuchAlgorithmException e) {
62	            // Retry using the current crypto provider's override implementation
63	            return CryptoIntegration.getProvider().getSignature(key.getAlgorithmOrDefault());
64	        }
65	    }
66	}
