342	   /**
343	    * Encode '%' if it is not an encoding sequence
344	    *
345	    * @param string
346	    * @return
347	    */
348	   public static String encodeNonCodes(String string)
349	   {
350	      Matcher matcher = nonCodes.matcher(string);
351	      StringBuilder builder = new StringBuilder();
352	
353	
354	      // FYI: we do not use the no-arg matcher.find()
355	      //      coupled with matcher.appendReplacement()
356	      //      because the matched text may contain
357	      //      a second % and we must make sure we
358	      //      encode it (if necessary).
359	      int idx = 0;
360	      while (matcher.find(idx))
361	      {
362	         int start = matcher.start();
363	         builder.append(string.substring(idx, start));
364	         builder.append("%25");
365	         idx = start + 1;
366	      }
367	      builder.append(string.substring(idx));
368	      return builder.toString();
369	   }
