371	   public static boolean savePathParams(String segment, StringBuilder newSegment, List<String> params)
372	   {
373	      boolean foundParam = false;
374	      // Regular expressions can have '{' and '}' characters.  Replace them to do match
375	      segment = PathHelper.replaceEnclosedCurlyBraces(segment);
376	      Matcher matcher = PathHelper.URI_TEMPLATE_PATTERN.matcher(segment);
377	      int start = 0;
378	      while (matcher.find())
379	      {
380	    	 newSegment.append(segment, start, matcher.start());
381	         foundParam = true;
382	         String group = matcher.group();
383	         // Regular expressions can have '{' and '}' characters.  Recover earlier replacement
384	         params.add(PathHelper.recoverEnclosedCurlyBraces(group));
385	         newSegment.append("_resteasy_uri_parameter");
386	         start = matcher.end();
387	      }
388	      newSegment.append(segment, start, segment.length());
389	      return foundParam;
390	   }
