525	   protected static String encodeFromArray(String segment, String[] encodingMap, boolean encodePercent)
526	   {
527	      StringBuilder result = new StringBuilder();
528	      for (int i = 0; i < segment.length(); i++)
529	      {
530	    	 char currentChar = segment.charAt(i);
531	         if (!encodePercent && currentChar == '%')
532	         {
533	            result.append(currentChar);
534	            continue;
535	         }
536	         String encoding = encode(currentChar, encodingMap);
537	         if (encoding == null)
538	         {
539	            result.append(currentChar);
540	         }
541	         else
542	         {
543	            result.append(encoding);
544	         }
545	      }
546	      return result.toString();
547	   }
