549	   /**
550	    * @param zhar        integer representation of character
551	    * @param encodingMap encoding map
552	    * @return URL encoded character
553	    */
554	   private static String encode(int zhar, String[] encodingMap)
555	   {
556	      String encoded;
557	      if (zhar < encodingMap.length)
558	      {
559	         encoded = encodingMap[zhar];
560	      }
561	      else
562	      {
563	         try
564	         {
565	            encoded = URLEncoder.encode(Character.toString((char) zhar), UTF_8);
566	         }
567	         catch (UnsupportedEncodingException e)
568	         {
569	            throw new RuntimeException(e);
570	         }
571	      }
572	      return encoded;
573	   }
