576	   {
577	      StringBuilder newSegment = new StringBuilder();
578	      Matcher matcher = PARAM_REPLACEMENT.matcher(segment);
579	      int i = 0;
580	      int start = 0;
581	      while (matcher.find())
582	      {
583	    	 newSegment.append(segment, start, matcher.start());
584	         String replacement = params.get(i++);
585	     	 newSegment.append(replacement);
586			 start = matcher.end();
587	      }
588	  	  newSegment.append(segment, start, segment.length());
589	      segment = newSegment.toString();
590	      return segment;
591	   }
