595	    *
596	    * @param map
597	    * @return
598	    */
599	   public static MultivaluedHashMap<String, String> decode(MultivaluedHashMap<String, String> map)
600	   {
601	       MultivaluedHashMap<String, String> decoded = new MultivaluedHashMap<String, String>();
602	      for (Map.Entry<String, List<String>> entry : map.entrySet())
603	      {
604	         List<String> values = entry.getValue();
605	         for (String value : values)
606	         {
607	            try
608	            {
609	               decoded.add(URLDecoder.decode(entry.getKey(), UTF_8), URLDecoder.decode(value, UTF_8));
610	            }
611	            catch (UnsupportedEncodingException e)
612	            {
613	               throw new RuntimeException(e);
614	            }
615	         }
616	      }
617	      return decoded;
618	   }
