113	    protected String encodeHeader(String sigAlgName) {
114	        StringBuilder builder = new StringBuilder("{");
115	
116	        if (org.keycloak.crypto.Algorithm.Ed25519.equals(sigAlgName) || org.keycloak.crypto.Algorithm.Ed448.equals(sigAlgName)) {
117	            builder.append("\"alg\":\"").append(org.keycloak.crypto.Algorithm.EdDSA).append("\"");
118	            builder.append(",\"crv\":\"").append(sigAlgName).append("\"");
119	        } else {
120	            builder.append("\"alg\":\"").append(sigAlgName).append("\"");
121	        }
122	
123	        if (type != null) builder.append(",\"typ\" : \"").append(type).append("\"");
124	        if (kid != null) builder.append(",\"kid\" : \"").append(kid).append("\"");
125	        if (x5t != null) builder.append(",\"x5t\" : \"").append(x5t).append("\"");
126	        if (x5c != null && !x5c.isEmpty()) {
127	            builder.append(",\"x5c\" : [");
128	            for (int i = 0; i < x5c.size(); i++) {
129	                String certificate = x5c.get(i);
130	                if (i > 0) {
131	                    builder.append(",");
132	                }
133	                builder.append("\"").append(certificate).append("\"");
134	            }
135	            builder.append("]");
136	        }
137	        if (jwk != null) {
138	            try {
139	                builder.append(",\"jwk\" : ").append(KeycloakJsonMapperFactory.mapper().writeValueAsString(jwk));
140	            } catch (IOException e) {
141	                throw new RuntimeException(e);
142	            }
143	        }
144	        if (contentType != null) builder.append(",\"cty\":\"").append(contentType).append("\"");
145	        builder.append("}");
146	        return Base64Url.encode(builder.toString().getBytes(StandardCharsets.UTF_8));
147	    }
