38	public class Encode
39	{
40	   private static final String UTF_8 = StandardCharsets.UTF_8.name();
41	
42	   private static final Pattern PARAM_REPLACEMENT = Pattern.compile("_resteasy_uri_parameter");
43	
44	   private static final String[] pathEncoding = new String[128];
45	   private static final String[] pathSegmentEncoding = new String[128];
46	   private static final String[] matrixParameterEncoding = new String[128];
47	   private static final String[] queryNameValueEncoding = new String[128];
48	   private static final String[] queryStringEncoding = new String[128];
49	   private static final String[] userInfoStringEncoding = new String[128];
50	
51	   static
52	   {
53	      /*
54	       * Encode via <a href="http://ietf.org/rfc/rfc3986.txt">RFC 3986</a>.  PCHAR is allowed allong with '/'
55	       *
56	       * unreserved  = ALPHA / DIGIT / "-" / "." / "_" / "~"
57	       * sub-delims  = "!" / "$" / "&" / "'" / "(" / ")"
58	                     / "*" / "+" / "," / ";" / "="
59	       * pchar = unreserved / pct-encoded / sub-delims / ":" / "@"
60	       *
61	       */
62	      for (int i = 0; i < 128; i++)
63	      {
64	         if (i >= 'a' && i <= 'z') continue;
65	         if (i >= 'A' && i <= 'Z') continue;
66	         if (i >= '0' && i <= '9') continue;
67	         switch ((char) i)
68	         {
69	            case '-':
70	            case '.':
71	            case '_':
72	            case '~':
73	            case '!':
74	            case '$':
75	            case '&':
76	            case '\'':
77	            case '(':
78	            case ')':
79	            case '*':
80	            case '+':
81	            case ',':
82	            case '/':
83	            case ';':
84	            case '=':
85	            case ':':
86	            case '@':
87	               continue;
88	         }
89	         try {
90	            pathEncoding[i] = URLEncoder.encode(String.valueOf((char) i), UTF_8);
91	         } catch (UnsupportedEncodingException e) {
92	            throw new RuntimeException(e);
93	         }
94	      }
95	      pathEncoding[' '] = "%20";
96	      System.arraycopy(pathEncoding, 0, matrixParameterEncoding, 0, pathEncoding.length);
97	      matrixParameterEncoding[';'] = "%3B";
98	      matrixParameterEncoding['='] = "%3D";
99	      matrixParameterEncoding['/'] = "%2F"; // RESTEASY-729
100	      System.arraycopy(pathEncoding, 0, pathSegmentEncoding, 0, pathEncoding.length);
101	      pathSegmentEncoding['/'] = "%2F";
102	      /*
103	       * Encode via <a href="http://ietf.org/rfc/rfc3986.txt">RFC 3986</a>.
104	       *
105	       * unreserved  = ALPHA / DIGIT / "-" / "." / "_" / "~"
106	       * space encoded as '+'
107	       *
108	       */
109	      for (int i = 0; i < 128; i++)
110	      {
111	         if (i >= 'a' && i <= 'z') continue;
112	         if (i >= 'A' && i <= 'Z') continue;
113	         if (i >= '0' && i <= '9') continue;
114	         switch ((char) i)
115	         {
116	            case '-':
117	            case '.':
118	            case '_':
119	            case '~':
120	            case '?':
121	               continue;
122	            case ' ':
123	               queryNameValueEncoding[i] = "+";
124	               continue;
125	         }
126	         try {
127	            queryNameValueEncoding[i] = URLEncoder.encode(String.valueOf((char) i), UTF_8);
128	         } catch (UnsupportedEncodingException e) {
129	            throw new RuntimeException(e);
130	         }
131	      }
132	
133	      /*
134	       * query       = *( pchar / "/" / "?" )
135	
136	       */
137	      for (int i = 0; i < 128; i++)
138	      {
139	         if (i >= 'a' && i <= 'z') continue;
140	         if (i >= 'A' && i <= 'Z') continue;
141	         if (i >= '0' && i <= '9') continue;
142	         switch ((char) i)
143	         {
144	            case '-':
145	            case '.':
146	            case '_':
147	            case '~':
148	            case '!':
149	            case '$':
150	            case '&':
151	            case '\'':
152	            case '(':
153	            case ')':
154	            case '*':
155	            case '+':
156	            case ',':
157	            case ';':
158	            case '=':
159	            case ':':
160	            case '@':
161	            case '?':
162	            case '/':
163	               continue;
164	            case ' ':
165	               queryStringEncoding[i] = "%20";
166	               continue;
167	         }
168	         try {
169	            queryStringEncoding[i] = URLEncoder.encode(String.valueOf((char) i), UTF_8);
170	         } catch (UnsupportedEncodingException e) {
171	            throw new RuntimeException(e);
172	         }
173	      }
174	
175	     /*
176	      * userinfo    = *( unreserved / pct-encoded / sub-delims / ":" )
177	      * unreserved  = ALPHA / DIGIT / "-" / "." / "_" / "~"
178	      * pct-encoded   = "%" HEXDIG HEXDIG
179	      * sub-delims  = "!" / "$" / "&" / "'" / "(" / ")"
180	      *                   / "*" / "+" / "," / ";" / "="
181	      */
182	      for (int i = 0; i < 128; i++)
183	      {
184	         if (i >= 'a' && i <= 'z') continue;
185	         if (i >= 'A' && i <= 'Z') continue;
186	         if (i >= '0' && i <= '9') continue;
187	         switch ((char) i)
188	         {
189	            case '-':
190	            case '.':
191	            case '_':
192	            case '~':
193	            case '!':
194	            case '$':
195	            case '&':
196	            case '\'':
197	            case '(':
198	            case ')':
199	            case '*':
200	            case '+':
201	            case ',':
202	            case ';':
203	            case '=':
204	            case ':':
205	               continue;
206	            case ' ':
207	               userInfoStringEncoding[i] = "%20";
208	               continue;
209	         }
210	         userInfoStringEncoding[i] = URLEncoder.encode(String.valueOf((char) i));
211	      }
212	   }
