299	   //private static final Pattern nonCodes = Pattern.compile("%([^a-fA-F0-9]|$)");
300	   private static final Pattern nonCodes = Pattern.compile("%([^a-fA-F0-9]|[a-fA-F0-9]$|$|[a-fA-F0-9][^a-fA-F0-9])");
301	   private static final Pattern encodedChars = Pattern.compile("%([a-fA-F0-9][a-fA-F0-9])");
302	   private static final Pattern encodedCharsMulti = Pattern.compile("((%[a-fA-F0-9][a-fA-F0-9])+)");
303	
304	   public static String decodePath(String path)
305	   {
306	      Matcher matcher = encodedCharsMulti.matcher(path);
307	      int start=0;
308	      StringBuilder builder = new StringBuilder();
309	      CharsetDecoder decoder = Charset.forName(UTF_8).newDecoder();
310	      while (matcher.find())
311	      {
312	    	 builder.append(path, start, matcher.start());
313	         decoder.reset();
314	         String decoded = decodeBytes(matcher.group(1), decoder);
315	         builder.append(decoded);
316	         start = matcher.end();
317	      }
318	      builder.append(path, start, path.length());
319	      return builder.toString();
320	   }
321	
322	   private static String decodeBytes(String enc, CharsetDecoder decoder)
323	   {
324	      Matcher matcher = encodedChars.matcher(enc);
325	      ByteBuffer bytes = ByteBuffer.allocate(enc.length() / 3);
326	      while (matcher.find())
327	      {
328	         int b = Integer.parseInt(matcher.group(1), 16);
329	         bytes.put((byte) b);
330	      }
331	      bytes.flip();
332	      try
333	      {
334	         return decoder.decode(bytes).toString();
335	      }
336	      catch (CharacterCodingException e)
337	      {
338	         throw new RuntimeException(e);
339	      }
340	   }
