161	    private static <T extends StoreFormat> String getStoreType(String preferredType, String path, String defaultType, T[] values) {
162	        // Configured type has precedence
163	        if (preferredType != null) {
164	            return preferredType;
165	        }
166	
167	        // Fallback to path
168	        Optional<StoreFormat> format = getStoreFormat(path, values);
169	        if (format.isPresent()) {
170	            return format.get().toString();
171	        }
172	
173	        // Fallback to default
174	        return defaultType;
175	    }
